"use client";
// TEMPORARY tooth-capture harness. Reproduces the REAL single-tooth view by
// reusing DentalCanvas's CameraController + ZoneCameraRotator + OrbitControls,
// then POSTs a transparent PNG of each tooth's initial view to /api/save-tooth,
// named by FDI. Safe to delete afterward.
import { useEffect, useRef, useState } from "react";
import { Canvas } from "@react-three/fiber";
import { OrbitControls, useGLTF } from "@react-three/drei";
import { Suspense } from "react";
import { Tooth } from "@/components/dental/examination/Tooth";
import { CameraController, ZoneCameraRotator } from "@/components/dental/examination/DentalCanvas";
import { TEETH } from "@/components/dental/examination/types";

// Match the single-tooth view's CSS panel dimensions so the camera framing
// (which is width/height-aware) equals what the doctor sees.
const CSS_W = 361;
const CSS_H = 577;

export default function ToothCapturePage() {
  const [idx, setIdx] = useState(0);
  const [status, setStatus] = useState("idle");
  const controlsRef = useRef(null);

  useEffect(() => {
    TEETH.forEach((t) => { try { useGLTF.preload(t.modelPath); } catch {} });
  }, []);

  useEffect(() => {
    window.__teeth = TEETH.map((t) => t.fdi);
    window.__setTooth = (i) => setIdx(i);
    window.__progress = { i: 0, total: TEETH.length, done: false, saved: [], phase: "idle" };
    const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    window.__runCapture = async () => {
      if (window.__capturing) return;
      window.__capturing = true;
      setStatus("warming");
      window.__progress = { i: 0, total: TEETH.length, done: false, saved: [], phase: "warm" };
      for (let i = 0; i < TEETH.length; i++) { setIdx(i); window.__progress.i = i; await sleep(900); }
      await sleep(800);
      setStatus("capturing");
      window.__progress.phase = "capture";
      for (let i = 0; i < TEETH.length; i++) {
        setIdx(i);
        window.__progress.i = i;
        await sleep(2200); // allow camera framing animation + render to settle
        const cv = document.querySelector("#cap-host canvas");
        let url = null;
        try { url = cv && cv.toDataURL("image/png"); } catch {}
        if (url && url.length > 5000) {
          try {
            const res = await fetch("/api/save-tooth", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ fdi: TEETH[i].fdi, dataUrl: url }),
            });
            const j = await res.json();
            if (j.ok) window.__progress.saved.push(TEETH[i].fdi);
          } catch {}
        }
      }
      window.__progress.done = true;
      window.__capturing = false;
      setStatus("done");
    };
  }, []);

  const t = TEETH[idx];
  return (
    <div style={{ padding: 20, fontFamily: "Inter, sans-serif" }}>
      <h1 style={{ fontSize: 16 }}>Tooth capture harness (real single-tooth view)</h1>
      <p style={{ fontSize: 13, color: "#475569" }}>Status: {status} · current FDI: {t.fdi} ({t.name})</p>
      <button onClick={() => window.__runCapture()} style={{ padding: "8px 14px", borderRadius: 8, border: "1px solid #cbd5e1", cursor: "pointer" }}>Run capture</button>
      <div id="cap-host" style={{ width: CSS_W, height: CSS_H, marginTop: 16, background: "transparent" }}>
        <Canvas
          camera={{ position: [0, 2.5, 13], fov: 35 }}
          dpr={[2, 3]}
          gl={{ antialias: true, alpha: true, preserveDrawingBuffer: true, toneMapping: 3, toneMappingExposure: 1.3, powerPreference: "high-performance" }}
          style={{ width: "100%", height: "100%", background: "transparent" }}
        >
          <ambientLight intensity={0.8} />
          <directionalLight position={[3, 5, 4]} intensity={1.0} />
          <directionalLight position={[-2, 3, -2]} intensity={0.4} />
          <directionalLight position={[0, -2, 1]} intensity={0.3} />
          <CameraController
            viewMode="single-tooth"
            patientType="adult"
            selectionScopeType="tooth"
            selectionScopeId={t.fdi}
            dentitionVerticalNudge={0}
            onDentitionVerticalNudgeChange={() => {}}
            controlsRef={controlsRef}
          />
          <ZoneCameraRotator zone={null} toothFdi={t.fdi} quadrant={t.quadrant} arch={t.arch} controlsRef={controlsRef} />
          <Suspense fallback={null}>
            <group position={[0, -0.17, 0]}>
              <Tooth
                modelPath={t.modelPath}
                arch={t.arch}
                mirrorX={t.mirrorX}
                quadrant={t.quadrant}
                toothPosition={t.position}
                toothFdi={t.fdi}
                selectedZone={null}
                onSelectZone={() => {}}
                onClearSelectedZone={() => {}}
                onHoverZone={() => {}}
                isImplant={false}
                findings={[]}
                zoneNotes={{}}
                toothDiagnoses={new Set()}
                multiSelectZones={[]}
                multiSelectActive={false}
                hideTags
                treatmentHistoryDetails={{}}
                toothEntries={[]}
              />
            </group>
          </Suspense>
          <OrbitControls ref={controlsRef} enableDamping dampingFactor={0.12} enablePan={false} minDistance={2.05} maxDistance={10.5} />
        </Canvas>
      </div>
    </div>
  );
}
